// ===== SCENE TABLE =====
// Add a scene = one row here + one case on each dispatch switch + wires.
var SCENES = {
    "input_boolean.movie_switch":        { key: "movie", status: "Movie Time" },
    "input_boolean.wii_switch":          { key: "wii",   status: "Play Time" },
    "input_boolean.reading_switch":      { key: "music", status: "Playing Music" },
    "input_boolean.whatsapp_switch":     { key: "chat",  status: "WhatsApp" },
    "input_boolean.lounge_chill_switch": { key: "chill", status: "Chilling" },
    "input_boolean.xmas_switch":         { key: "xmas",  status: null, standalone: true }
};

var id = msg.data && msg.data.entity_id;
var sc = SCENES[id];
if (!sc) { return [null, null, null, null]; }        // unknown entity -> drop

if (msg.payload === "on") {
    msg.scene = sc.key;
    msg.sceneStatus = sc.status || "";
    return [msg, null, null, null];                  // 1: ON dispatch
}
if (msg.payload === "off") {
    msg.scene = sc.key;
    if (sc.standalone) {
        return [null, null, null, msg];              // 4: xmas off -> plugs off
    }
    // separate copies: teardown branch and none-on check run independently
    return [null, Object.assign({}, msg), Object.assign({}, msg), null];
                                                   // 2: OFF dispatch, 3: none-on check
}
return [null, null, null, null];   // unavailable/unknown ignored (live did not)
